const express = require('express');
const crypto = require('crypto');
const { RateLimiterMemory } = require('rate-limiter-flexible');

const app = express();
app.use(express.json({ limit: '10mb' }));

// Rate limiter: 10 indexing requests per minute per user
const indexRateLimiter = new RateLimiterMemory({
  points: 10,
  duration: 60,
});

// Search index storage
const searchIndex = new Map();
const userQuotas = new Map();

const MAX_DOCUMENTS_PER_USER = 1000;
const MAX_BATCH_SIZE = 50;

// Middleware to extract and validate user identity
function authenticateUser(req, res, next) {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey || typeof apiKey !== 'string' || apiKey.length < 16) {
    return res.status(401).json({ error: 'Invalid API key' });
  }
  // Derive user ID from API key
  req.userId = crypto.createHash('sha256').update(apiKey).digest('hex').slice(0, 16);
  next();
}

// Compute rate limit key from request context
function computeRateLimitKey(req) {
  const userId = req.userId;
  return userId;
}

// Validate document structure
function validateDocument(doc) {
  if (!doc || typeof doc !== 'object') return false;
  if (typeof doc.id !== 'string' || doc.id.length === 0 || doc.id.length > 128) return false;
  if (typeof doc.content !== 'string' || doc.content.length > 50000) return false;
  if (doc.tags && !Array.isArray(doc.tags)) return false;
  if (doc.tags && doc.tags.length > 20) return false;
  return true;
}

// Tokenize content for indexing
function tokenizeContent(content) {
  return content.toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(token => token.length >= 2 && token.length <= 40)
    .slice(0, 500);
}

// Index a single document
function indexDocument(userId, doc) {
  const tokens = tokenizeContent(doc.content);
  const entry = {
    id: doc.id,
    tokens,
    tags: (doc.tags || []).map(t => String(t).slice(0, 50)),
    indexedAt: Date.now(),
    userId
  };

  const userIndex = searchIndex.get(userId) || new Map();
  userIndex.set(doc.id, entry);
  searchIndex.set(userId, userIndex);
  return entry;
}

// POST /api/index - Single document indexing
app.post('/api/index', authenticateUser, async (req, res) => {
  try {
    const rateLimitKey = computeRateLimitKey(req);
    await indexRateLimiter.consume(rateLimitKey, 1);
  } catch (rateLimitErr) {
    return res.status(429).json({ error: 'Rate limit exceeded', retryAfter: rateLimitErr.msBeforeNext / 1000 });
  }

  const doc = req.body;
  if (!validateDocument(doc)) {
    return res.status(400).json({ error: 'Invalid document structure' });
  }

  const userIndex = searchIndex.get(req.userId) || new Map();
  if (userIndex.size >= MAX_DOCUMENTS_PER_USER) {
    return res.status(403).json({ error: 'Document quota exceeded' });
  }

  const entry = indexDocument(req.userId, doc);
  res.status(201).json({ indexed: true, documentId: entry.id, tokens: entry.tokens.length });
});

// POST /api/index/batch - Batch document indexing
app.post('/api/index/batch', authenticateUser, async (req, res) => {
  const documents = req.body.documents;
  if (!Array.isArray(documents) || documents.length === 0) {
    return res.status(400).json({ error: 'documents must be a non-empty array' });
  }
  if (documents.length > MAX_BATCH_SIZE) {
    return res.status(400).json({ error: `Batch size exceeds maximum of ${MAX_BATCH_SIZE}` });
  }

  try {
    const rateLimitKey = computeRateLimitKey(req);
    // Consume points based on batch size
    const pointsToConsume = Math.ceil(documents.length / 5);
    await indexRateLimiter.consume(rateLimitKey, pointsToConsume);
  } catch (rateLimitErr) {
    return res.status(429).json({ error: 'Rate limit exceeded', retryAfter: rateLimitErr.msBeforeNext / 1000 });
  }

  const results = [];
  const userIndex = searchIndex.get(req.userId) || new Map();

  for (const doc of documents) {
    if (!validateDocument(doc)) {
      results.push({ id: doc?.id, error: 'Invalid document' });
      continue;
    }
    if (userIndex.size >= MAX_DOCUMENTS_PER_USER) {
      results.push({ id: doc.id, error: 'Quota exceeded' });
      continue;
    }
    const entry = indexDocument(req.userId, doc);
    results.push({ id: entry.id, indexed: true });
  }

  res.json({ results, processed: results.filter(r => r.indexed).length });
});

// GET /api/search
app.get('/api/search', authenticateUser, async (req, res) => {
  const query = req.query.q;
  if (!query || typeof query !== 'string' || query.length > 200) {
    return res.status(400).json({ error: 'Invalid query' });
  }

  const queryTokens = tokenizeContent(query);
  const userIndex = searchIndex.get(req.userId);
  if (!userIndex) return res.json({ results: [] });

  const results = [];
  for (const [docId, entry] of userIndex) {
    const score = queryTokens.filter(qt => entry.tokens.includes(qt)).length;
    if (score > 0) results.push({ id: docId, score, tags: entry.tags });
  }

  results.sort((a, b) => b.score - a.score);
  res.json({ results: results.slice(0, 20) });
});

app.listen(3000, () => console.log('Search indexing service running on port 3000'));

module.exports = app;
